"""What differs between the four Roadmap Projects: the title, the text, the families and the work items.

HYDRA-UMC keeps its definitions where they always were (bootstrap_ecosystem_project.py and seed_ecosystem_roadmap.py). URTC, A.R.M.O.R. and EH3D each have their own board, with the
same fields and views as that one (so a person who knows one knows all four) but their own families, hardware dependencies and a human-curated list of planning items. As in
the HYDRA-UMC board, an item is a record of a scoped, evidence-based next step; it is never a claim that something physical was validated.

Each board also has STATUS_UPDATES (title -> status, and what blocks it) and RENAMES (old title -> new title). Both are explicit and reviewable, and the seeder applies them only
when it runs with --reconcile-status, so a card nobody listed keeps whatever a person did with it.
"""

from __future__ import annotations

from typing import Any


def _status(status: str, blocked_by: str = "None") -> dict[str, str]:
    """One explicit status decision for an existing card."""
    return {"status": status, "blocked_by": blocked_by}


def _item(title: str, repository: str, family: str, maturity: str, evidence: str, priority: str, objective: str, acceptance: str,
          status: str = "Backlog", hardware: str = "None", blocked_by: str = "None") -> dict[str, str]:
    return {"title": title, "repository": repository, "family": family, "maturity": maturity, "evidence": evidence, "priority": priority,
            "objective": objective, "acceptance": acceptance, "status": status, "hardware": hardware, "blocked_by": blocked_by}


